     useEffect(() => {
        const verifyPayment = async () => {
            // 1. Try to get payment_id from URL
            const params = new URLSearchParams(window.location.search);
            let paymentId = params.get('payment_id');

            try {
                // 2. If Yoco removed it from the URL, look for the most recent pending payment
                if (!paymentId && user?.id) {
                    const { data: latestPayment } = await supabase
                        .from('subscription_payments')
                        .select('*')
                        .eq('user_id', user.id)
                        .eq('status', 'pending')
                        .order('created_at', { ascending: false })
                        .limit(1)
                        .single();

                    if (latestPayment) paymentId = latestPayment.id;
                }

                if (!paymentId) {
                    setLoading(false);
                    showToast('Payment completed, but we could not verify the ID.', 'warning');
                    return;
                }

                // 3. Fetch the payment record
                const { data: payment, error } = await supabase
                    .from('subscription_payments')
                    .select('*')
                    .eq('id', paymentId)
                    .single();

                if (error) throw error;
                if (!payment) throw new Error('Payment record not found');

                // 4. Mark payment as success
                if (payment.status === 'pending') {
                    await supabase
                        .from('subscription_payments')
                        .update({ status: 'success' })
                        .eq('id', paymentId);
                }

                // 5. Handle Setup Fee (R100)
                if (payment.type === 'community' && payment.amount === 100) {
                    await supabase
                        .from('communities')
                        .update({ setup_fee_paid: true, setup_fee_paid_at: new Date().toISOString() })
                        .eq('id', payment.community_id);
                    
                    setCommunityId(payment.community_id);
                    showToast('Community created! Setup fee paid.', 'success');
                } 
                // 6. Handle Premium Subscription (R60)
                else if (payment.type === 'premium') {
                    setIsPremium(true);
                    showToast('Premium subscription activated!', 'success');
                }

            } catch (error) {
                console.error('Error verifying payment:', error);
                showToast('Payment verification failed.', 'error');
            } finally {
                setLoading(false);
            }
        };

        if (user) verifyPayment();
        else {
            setLoading(false);
            showToast('Please log in to verify your payment.', 'warning');
        }
    }, [user, showToast]);
